diff --git a/mail/components/calendar/content/calendar-dialog-description-row.mjs b/mail/components/calendar/content/calendar-dialog-description-row.mjs
index bfe91da1fbd..c57a1258f4f 100644
--- a/mail/components/calendar/content/calendar-dialog-description-row.mjs
+++ b/mail/components/calendar/content/calendar-dialog-description-row.mjs
@@ -136,7 +136,9 @@ class CalendarDialogDescriptionRow extends HTMLElement {
     }

     if (!description && !descriptionHTML) {
-      this.#browser?.contentDocument.body.replaceChildren();
+      // Disconnecting the row can remove the browser's document.
+      this.#browser?.contentDocument?.body.replaceChildren();
+
       return;
     }

diff --git a/mail/components/calendar/test/browser/browser_calendarDialogDescriptionRow.js b/mail/components/calendar/test/browser/browser_calendarDialogDescriptionRow.js
index 9b940ac4c08..07581855d5d 100644
--- a/mail/components/calendar/test/browser/browser_calendarDialogDescriptionRow.js
+++ b/mail/components/calendar/test/browser/browser_calendarDialogDescriptionRow.js
@@ -2,6 +2,8 @@
  * License, v. 2.0. If a copy of the MPL was not distributed with this
  * file, you can obtain one at http://mozilla.org/MPL/2.0/. */

+"use strict";
+
 const tabmail = document.getElementById("tabmail");
 let expandingDescription, expandedDescription;
 let richDescription;
@@ -150,3 +152,56 @@ add_task(async function test_setExpandingDescription() {
     "Should still not touch browser"
   );
 });
+
+add_task(async function test_clearDisconnectedDescription() {
+  const plainText = expandedDescription.querySelector(
+    ".plain-text-description"
+  );
+  const description = "Description to clear";
+
+  expandedDescription.setDescription(description);
+
+  await TestUtils.waitForCondition(
+    () =>
+      richDescription.contentDocument?.body.textContent.trim() == description,
+    "The rich description should contain the text before clearing."
+  );
+
+  expandedDescription.setDescription("");
+
+  Assert.equal(
+    plainText.textContent,
+    "",
+    "Clearing the connected row should clear its plain text."
+  );
+  Assert.equal(
+    richDescription.contentDocument.body.childElementCount,
+    0,
+    "Clearing the connected row should clear its rich content."
+  );
+
+  expandedDescription.setDescription(description);
+
+  Assert.equal(
+    richDescription.contentDocument.body.textContent.trim(),
+    description,
+    "The rich description should contain text before disconnecting."
+  );
+
+  // Replacing the read dialog removes the row and its browser document.
+  expandedDescription.remove();
+
+  Assert.equal(
+    richDescription.contentDocument,
+    null,
+    "Removing the row should destroy its browser document."
+  );
+
+  expandedDescription.setDescription("");
+
+  Assert.equal(
+    plainText.textContent,
+    "",
+    "Clearing the disconnected row should clear its plain text."
+  );
+});
